using Xunit;

namespace FreightValueTypes.Tests;

/// <summary>
/// Value equality and hash-code consistency for the three
/// <c>readonly record struct</c> types: two independently constructed values
/// with the same field values are equal through <c>Equals</c> and <c>==</c>,
/// share a hash code, and compare unequal the moment any field differs.
/// None of this is hand-written on <see cref="Money"/>, <see cref="Weight"/>,
/// or <see cref="SlotId"/>; it is generated by the record struct declaration.
/// </summary>
public sealed class ValueEqualityTests
{
    [Fact]
    public void Money_with_same_fields_is_equal_and_shares_hash_code()
    {
        var left = new Money(42.50m, "USD");
        var right = new Money(42.50m, "USD");

        Assert.Equal(left, right);
        Assert.True(left == right);
        Assert.False(left != right);
        Assert.Equal(left.GetHashCode(), right.GetHashCode());
    }

    [Theory]
    [InlineData(42.50, "EUR")]
    [InlineData(10.00, "USD")]
    public void Money_differing_in_any_field_is_not_equal(decimal amount, string currency)
    {
        var baseline = new Money(42.50m, "USD");
        var other = new Money(amount, currency);

        Assert.NotEqual(baseline, other);
        Assert.False(baseline == other);
        Assert.True(baseline != other);
    }

    [Fact]
    public void Weight_with_same_kilograms_is_equal_and_shares_hash_code()
    {
        var left = new Weight(125.5m);
        var right = new Weight(125.5m);

        Assert.Equal(left, right);
        Assert.True(left == right);
        Assert.Equal(left.GetHashCode(), right.GetHashCode());
    }

    [Fact]
    public void Weight_with_different_kilograms_is_not_equal()
    {
        var left = new Weight(125.5m);
        var right = new Weight(99.0m);

        Assert.NotEqual(left, right);
        Assert.True(left != right);
    }

    [Fact]
    public void SlotId_with_same_bay_and_tier_is_equal_and_shares_hash_code()
    {
        var left = new SlotId(3, 2);
        var right = new SlotId(3, 2);

        Assert.Equal(left, right);
        Assert.True(left == right);
        Assert.Equal(left.GetHashCode(), right.GetHashCode());
    }

    [Theory]
    [InlineData(3, 9)]
    [InlineData(9, 2)]
    public void SlotId_differing_in_bay_or_tier_is_not_equal(int bay, int tier)
    {
        var baseline = new SlotId(3, 2);
        var other = new SlotId(bay, tier);

        Assert.NotEqual(baseline, other);
        Assert.True(baseline != other);
    }

    [Fact]
    public void Value_semantics_mean_assignment_copies_not_aliases()
    {
        var original = new Weight(10m);
        var copy = original;
        copy = copy with { Kilograms = 999m };

        Assert.Equal(10m, original.Kilograms);
        Assert.Equal(999m, copy.Kilograms);
        Assert.NotEqual(original, copy);
    }

    [Fact]
    public void Two_independently_constructed_equal_consignment_records_compare_equal()
    {
        var first = new ConsignmentRecord(4217, new SlotId(3, 2), new Weight(125.5m), new Money(450.75m, "USD"));
        var second = new ConsignmentRecord(4217, new SlotId(3, 2), new Weight(125.5m), new Money(450.75m, "USD"));

        Assert.Equal(first, second);
        Assert.True(first == second);
    }
}
